/**
 * Return true only when the current authoritative Turn state already
 * contains an unexecuted committed entry for this exact semantic action.
 *
 * Planning-time Turn state has already spent the action budget for such an
 * entry, so canonical effect execution must not spend the same budget again.
 * Non-committed callers continue through ordinary action-economy validation.
 */
function frameConnActionHasPrecommittedTurnEconomy(
  action
) {
  const turnState =
    getFrameConnTurnState();

  if (
    !action?.id ||
    !Array.isArray(
      turnState?.usedActions
    )
  ) {
    return false;
  }

  return turnState.usedActions.some(
    entry =>
      entry?.actionId === action.id &&
      entry?.executed !== true
  );
}

semanticActionId:
